:root{--bg:#07111e;--panel:#0d1b2e;--panel2:#0f2442;--line:#1e3556;--text:#eaf0fb;--dim:#c7d6ec;--faint:#9cb0cf;--accent:#7c9eff;--ok:#5ad1a5;--warn:#f2c35c;--sw:290px}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;background:var(--bg);color:var(--text);font-family:"Noto Sans JP","Hiragino Kaku Gothic ProN","Yu Gothic","Meiryo",sans-serif;line-height:1.85;font-size:16px;overflow-x:hidden}
.sidebar{position:fixed;left:0;top:0;bottom:0;width:var(--sw);background:var(--panel);border-right:1px solid var(--line);overflow-y:auto;padding:20px 14px 40px;z-index:20}
.brand{font-weight:800;color:var(--accent);font-size:15px;padding:0 8px 14px;border-bottom:1px solid var(--line);margin-bottom:12px}
.brand small{display:block;color:var(--faint);font-weight:500;font-size:12px;margin-top:2px}
.sidebar ul{list-style:none;margin:0;padding:0}
.sidebar .n2>a{font-weight:700;color:var(--text)}
.sidebar .n2>ul{margin:2px 0 8px 10px;border-left:1px solid var(--line)}
.sidebar a{display:block;padding:5px 10px;color:var(--dim);text-decoration:none;font-size:13px;line-height:1.5;border-radius:6px}
.sidebar a:hover{background:var(--panel2)}
.sidebar a.active{background:rgba(124,158,255,.16);color:var(--accent)}
.main{margin-left:var(--sw);padding:36px 48px 80px}
.hero{position:relative;padding:34px 32px;border:1px solid var(--line);border-radius:16px;background:linear-gradient(135deg,#0d1b2e,#0a1626);overflow:hidden;margin-bottom:28px}
.hero::before{content:"";position:absolute;top:-80px;right:-80px;width:320px;height:320px;background:radial-gradient(circle,rgba(124,158,255,.28),transparent 70%)}
.badge{display:inline-block;padding:4px 12px;border:1px solid var(--accent);border-radius:999px;color:var(--accent);font-size:11px;letter-spacing:.06em;font-weight:700}
.hero-title{font-size:28px;font-weight:800;margin:14px 0 8px;color:#fff;line-height:1.4}
.hero-sub{margin:0;color:var(--dim)}
h2{font-size:23px;margin:56px 0 16px;padding:10px 0 10px 14px;border-left:4px solid var(--accent);background:linear-gradient(90deg,rgba(124,158,255,.1),transparent);scroll-margin-top:16px}
h3{font-size:18px;margin:34px 0 10px;color:#fff;scroll-margin-top:16px}
h4{font-size:16px;margin:28px 0 8px;color:var(--accent);scroll-margin-top:16px}
p,li{color:var(--dim)}
strong{color:#fff}
a{color:var(--accent)}
hr{border:0;border-top:1px solid var(--line);margin:36px 0}
code{background:var(--panel2);padding:1px 6px;border-radius:4px;font-size:.92em;word-break:break-word}
.callout{background:rgba(124,158,255,.1);border:1px solid rgba(124,158,255,.35);border-left:4px solid var(--accent);border-radius:10px;padding:12px 16px;color:var(--text)}
.glossary{margin:22px 0;background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:6px 18px 10px}
.glossary p{color:var(--warn);font-weight:700;margin:8px 0 2px}
.glossary ul{margin:4px 0;padding-left:20px}
.node-note{color:var(--faint);font-weight:700;margin-bottom:2px}
.table-scroll{overflow-x:auto;margin:14px 0 22px;border:1px solid var(--line);border-radius:10px}
table{border-collapse:collapse;width:100%;font-size:14.5px}
th{background:var(--panel2);color:#fff;text-align:left;white-space:nowrap}
th,td{padding:9px 14px;border-bottom:1px solid var(--line);vertical-align:top}
tr:last-child td{border-bottom:0}
tbody tr:nth-child(even){background:rgba(15,36,66,.45)}
.mermaid-diagram{display:block;overflow-x:auto;background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:20px;margin:16px 0}
.mermaid-diagram svg{display:block;margin-left:auto;margin-right:auto;max-width:none;flex-shrink:0}
.page-footer{margin-top:60px;padding-top:18px;border-top:1px solid var(--line);color:var(--faint);font-size:13px}
.nav-toggle{display:none;position:fixed;top:10px;left:10px;z-index:30;background:var(--panel2);color:var(--text);border:1px solid var(--line);border-radius:8px;padding:8px 12px;font-size:14px}
@media(max-width:900px){.nav-toggle{display:block}.sidebar{transform:translateX(-100%);transition:transform .2s}.sidebar.open{transform:none}.main{margin-left:0;padding:60px 16px 60px}.hero-title{font-size:22px}}

.checklist-card{margin:16px 0 26px;background:var(--panel);border:1px solid var(--line);border-radius:14px;overflow:hidden}
.checklist-progress{display:flex;align-items:center;gap:14px;padding:14px 18px;background:linear-gradient(90deg,rgba(124,158,255,.14),transparent);border-bottom:1px solid var(--line)}
.cl-label{font-weight:700;color:#fff;font-size:14px;white-space:nowrap}
.cl-bar{flex:1;height:8px;background:var(--panel2);border-radius:999px;overflow:hidden}
.cl-fill{height:100%;width:0;background:linear-gradient(90deg,var(--accent),var(--ok));border-radius:999px;transition:width .3s}
.cl-count{font-variant-numeric:tabular-nums;font-weight:700;color:var(--accent);font-size:14px;white-space:nowrap}
.cl-reset{background:transparent;color:var(--faint);border:1px solid var(--line);border-radius:6px;padding:3px 10px;font-size:12px;cursor:pointer;font-family:inherit}
.cl-reset:hover{color:var(--text);border-color:var(--accent)}
ul.checklist{list-style:none;margin:0;padding:6px 8px}
ul.checklist li{margin:2px 0}
ul.checklist .cl-txt{flex:1;line-height:1.6}
ul.checklist label{display:flex;align-items:center;gap:12px;padding:11px 12px;border-radius:10px;cursor:pointer;color:var(--dim);transition:background .15s,color .15s}
ul.checklist label:hover{background:rgba(124,158,255,.1)}
.cl-no{font-size:12px;font-weight:700;color:var(--faint);font-variant-numeric:tabular-nums;min-width:22px}
ul.checklist input{appearance:none;-webkit-appearance:none;flex:none;width:22px;height:22px;margin:0;border:2px solid #4a6fb5;border-radius:7px;background:var(--panel2);display:grid;place-content:center;cursor:pointer;transition:all .15s}
ul.checklist input::after{content:"";width:6px;height:11px;border:solid #07111e;border-width:0 2.5px 2.5px 0;transform:rotate(45deg) scale(0);transition:transform .15s;margin-top:-2px}
ul.checklist input:checked{background:var(--ok);border-color:var(--ok)}
ul.checklist input:checked::after{transform:rotate(45deg) scale(1)}
ul.checklist input:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
ul.checklist li.done label{color:var(--faint);background:rgba(90,209,165,.06)}
ul.checklist li.done .cl-txt{text-decoration:line-through;text-decoration-color:rgba(156,176,207,.6)}
.checklist-card.complete .checklist-progress{background:linear-gradient(90deg,rgba(90,209,165,.2),transparent)}
.checklist-card.complete .cl-count{color:var(--ok)}
@media(max-width:600px){.checklist-progress{flex-wrap:wrap}.cl-bar{order:3;flex-basis:100%}}

